import os, re
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Parse all demo pairs and test input
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]
print("Loaded grids:", sorted(G.keys()))
for name, grid in G.items():
    print(f"{name}: {grid}")

demo_in = [[0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0]]

def transform_simple(grid):
    """Simplest possible rule: value depends on parity and position."""
    h = w = len(grid[0])
    output = [[0]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            par = (r + c) % 2
            if par != 0:  # Odd sum
                output[r][c] = 0
            else:  # Even sum
                diff = abs(r - c)
                if diff % 6 == 0 and diff <= 6:  # On diagonal
                    output[r][c] = 2
                elif diff > 0 and diff <= 12:  # Off diagonal but "close"
                    output[r][c] = 1
                else:
                    output[r][c] = 0

    return output

result = transform_simple(demo_in)
print("Result matches expected:", result == demo_out)

if result != demo_out:
    mismatches = []
    for r in range(13):
        for c in range(13):
            if result[r][c] != demo_out[r][c]:
                mismatches.append((r,c, result[r][c], demo_out[r][c]))

    print(f"\n{len(mismatches)} mismatches:")
    for r,c,get_val,exp_val in mismatches[:20]:
        print(f"  ({r},{c}): got {get_val}, expected {exp_val}")

